export const getCoachScripts = (lang: 'en' | 'de') => (lang === 'de' ? COACH_SCRIPTS_DE : COACH_SCRIPTS);
export const getCoachStarters = (lang: 'en' | 'de') => (lang === 'de' ? COACH_STARTERS_DE : COACH_STARTERS);
export const getVoiceScripts = (lang: 'en' | 'de') => (lang === 'de' ? VOICE_SCRIPTS_DE : VOICE_SCRIPTS);
/** All scripts in every language, used to continue a saved demo conversation. */
export const ALL_COACH_SCRIPTS = () => [...COACH_SCRIPTS, ...COACH_SCRIPTS_DE];
